def find_max_sum_subarray_of_size_k(lst, k):
    n = len(lst)
    best = None
    for i in range(n - k + 1):
        window_sum = sum(lst[i:i + k])
        if best is None or window_sum > best:
            best = window_sum
    return best

def count_trailing_equal(lst):
    if not lst:
        return 0
    target = lst[-1]
    n = 0
    for i in range(len(lst) - 1, -1, -1):
        if lst[i] == target:
            n += 1
        else:
            break
    return n

